{
  "units": [
    {
      "quote_ref": "F000:F001",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Presents the section number and title for OSHA standard 1910.151, 'Medical services and first aid', containing no operative regulatory command or substantive rule in itself."
    },
    {
      "quote_ref": "F002",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "The employer is required to ensure that medical personnel are readily available for advice and consultation on matters of plant health."
    },
    {
      "quote_ref": "F003",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "In the absence of an infirmary, clinic, or hospital in near proximity to the workplace used for the treatment of all injured employees, a person or persons must be adequately trained to render first aid."
    },
    {
      "quote_ref": "F003",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Adequate first aid supplies must be readily available at the workplace."
    },
    {
      "quote_ref": "F004",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Where the eyes or body of any person may be exposed to injurious corrosive materials, suitable facilities for quick drenching or flushing of the eyes and body must be provided within the work area for immediate emergency use."
    },
    {
      "quote_ref": "F005",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Designates Appendix A to § 1910.151 regarding first aid kits as non-mandatory guidance."
    },
    {
      "quote_ref": "F006",
      "scope_refs": [
        "F005"
      ],
      "kind": "statement",
      "meaning": "Under Appendix A, paragraph § 1910.151(b) requires first aid supplies to be readily available, and an example of the minimal contents of a generic first aid kit is described in ANSI Z308.1-1998, 'Minimum Requirements for Workplace First-aid Kits'."
    },
    {
      "quote_ref": "F006",
      "scope_refs": [
        "F005"
      ],
      "kind": "recommendation",
      "meaning": "Under Appendix A, the contents of the first aid kit listed in the ANSI Z308.1-1998 standard should be adequate for small worksites."
    },
    {
      "quote_ref": "F006",
      "scope_refs": [
        "F005"
      ],
      "kind": "recommendation",
      "meaning": "Under Appendix A, when larger operations or multiple operations are conducted at the same location, employers should determine the need for additional first aid kits at the worksite, additional types of first aid equipment and supplies, and additional quantities and types of supplies and equipment in the first aid kits."
    },
    {
      "quote_ref": "F007",
      "scope_refs": [
        "F005"
      ],
      "kind": "statement",
      "meaning": "Under Appendix A, employers with unique or changing first-aid needs in their workplace may need to enhance their first-aid kits."
    },
    {
      "quote_ref": "F007",
      "scope_refs": [
        "F005"
      ],
      "kind": "permission",
      "meaning": "Under Appendix A, an employer can use the OSHA 300 log, OSHA 301 log, or other reports to identify unique first-aid problems in their workplace."
    },
    {
      "quote_ref": "F007",
      "scope_refs": [
        "F005"
      ],
      "kind": "statement",
      "meaning": "Under Appendix A, consultation from the local fire/rescue department, an appropriate medical professional, or a local emergency room may be helpful to employers dealing with unique or changing first-aid needs."
    },
    {
      "quote_ref": "F007",
      "scope_refs": [
        "F005"
      ],
      "kind": "statement",
      "meaning": "Under Appendix A, by assessing the specific needs of their workplace, employers can ensure that reasonably anticipated first aid supplies are available."
    },
    {
      "quote_ref": "F007",
      "scope_refs": [
        "F005"
      ],
      "kind": "recommendation",
      "meaning": "Under Appendix A, employers should assess the specific needs of their worksite periodically and augment the first aid kit appropriately."
    },
    {
      "quote_ref": "F008",
      "scope_refs": [
        "F005"
      ],
      "kind": "requirement",
      "meaning": "If it is reasonably anticipated that employees will be exposed to blood or other potentially infectious materials while using first aid supplies, employers are required to provide appropriate personal protective equipment (PPE) in compliance with the Occupational Exposure to Bloodborne Pathogens standard, § 1910.1030(d)(3)."
    },
    {
      "quote_ref": "F008",
      "scope_refs": [
        "F005"
      ],
      "kind": "statement",
      "meaning": "Under Appendix A, the Bloodborne Pathogens standard (§ 1910.1030(d)(3)) lists appropriate PPE for exposure to blood or other potentially infectious materials, such as gloves, gowns, face shields, masks, and eye protection."
    },
    {
      "quote_ref": "F009",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Provides editorial and historical rulemaking source notes and Federal Register citations for amendments to § 1910.151, containing no substantive employer obligations."
    }
  ]
}
